+{"id":"D105","cmd":"eval \"$(cat <<EOF\nrm -rf src\nEOF\n)\"","expect":"block","rule":"FR-6","why":"cat inside a substitution handed to eval","cwd":"repo"}
+{"id":"D106","cmd":"source <(cat <<EOF\nrm -rf src\nEOF\n)","expect":"block","rule":"FR-6","why":"cat inside a process substitution handed to source","cwd":"repo"}
+{"id":"D107","cmd":"ssh deploy@host bash <<EOF\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"ssh runs its argument: interpreter class","cwd":"repo"}
+{"id":"D108","cmd":"docker exec -i app sh <<EOF\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"docker exec runs its argument: interpreter class","cwd":"repo"}
+{"id":"D109","cmd":"sudo bash <<EOF\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"sudo wrapper around a shell","cwd":"repo"}
+{"id":"D110","cmd":"cat <<EOF | xargs -I{} sh -c '{}'\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"a pipe target that runs its input (xargs sh -c) makes the pipeline interpreter class","cwd":"repo"}
+{"id":"D111","cmd":"env python3 - <<PY\nimport os\nos.system(\"rm -rf src\")\nPY","expect":"block","rule":"FR-6","why":"env wrapper around an interpreter","cwd":"repo"}
