+{"id":"D114","cmd":"yq -i '.' ci.yaml <<'EOF'\nrun: rm -rf src\nEOF","expect":"block","rule":"FR-6","why":"yq in-place: the allowlist excludes -i, the body is scanned","cwd":"repo"}
+{"id":"D115","cmd":"jq -i '.cmd' <<'EOF'\n{\"cmd\": \"rm -rf src\"}\nEOF","expect":"block","rule":"FR-6","why":"jq with an in-place-shaped flag: the body is scanned","cwd":"repo"}
+{"id":"D116","cmd":"awk '{ system(\"rm -rf src\") }' <<'EOF'\nx\nEOF","expect":"block","rule":"FR-6","why":"awk can call system(): interpreter class, the header's own system() argument is scanned","cwd":"repo"}
+{"id":"D117","cmd":"sed 'e rm -rf src' <<'EOF'\nx\nEOF","expect":"block","rule":"FR-6","why":"sed with an e command is not the print-only form: interpreter class","cwd":"repo"}
