+{"id":"D119","cmd":"cat > x.sh <<'EOF'\nrm -rf src\nEOF\nbash x.sh","expect":"block","rule":"FR-6","why":"a heredoc written to x.sh and run on the same command (script extension and same-line execution)","cwd":"repo"}
+{"id":"D120","cmd":"cat > run <<'EOF'\nrm -rf src\nEOF\nchmod +x run && ./run","expect":"block","rule":"FR-6","why":"same-line execution of an extensionless target: chmod +x names the target outside a safe reader","cwd":"repo"}
+{"id":"D121","cmd":"tee setup.sh <<'EOF'\nrm -rf src\nEOF\nsource setup.sh","expect":"block","rule":"FR-6","why":"tee into a .sh then source on the same command","cwd":"repo"}
+{"id":"D122","cmd":"cat > cleanup.sh <<'EOF'\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"a .sh target with no later execution is executable content: scanned in full (the #1245 scrub let this through)","cwd":"repo"}
+{"id":"D123","cmd":"cat > cleanup <<'EOF'\n#!/bin/sh\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"a shebang first line makes a plain-file target executable content (the #1245 scrub let this through)","cwd":"repo"}
+{"id":"D124","cmd":"tee .claude/hooks/safety/x.sh <<'EOF'\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"a write under .claude/hooks/ is executable content (and FR-SZ2-TEE blocks the System Zone write regardless)","cwd":"repo"}
+{"id":"D125","cmd":"cat >> ~/.bashrc <<'EOF'\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"an rc file target is executable content","cwd":"repo"}
+{"id":"D126","cmd":"mycmd <<'EOF'\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"a consumer on neither list: full scan (the default)","cwd":"repo"}
+{"id":"D127","cmd":"cat > notes.md <<'EOF'\ncat <<'INNER'\nrm -rf src\nINNER\nEOF","expect":"block","rule":"FR-6","why":"a nested heredoc in the body forces the full scan","cwd":"repo"}
+{"id":"D128","cmd":"cat > notes.md <<$D\nrm -rf src\n$D","expect":"block","rule":"FR-6","why":"a variable-expanded delimiter cannot be paired: full scan","cwd":"repo"}
+{"id":"D129","cmd":"cat <<EOF > notes.md\necho ok && rm -rf src\nEOF","expect":"block","rule":"FR-6","why":"per-segment scan: the segment after && starts with a fence verb","cwd":"repo"}
+{"id":"D130","cmd":"cat <<EOF > notes.md\n; rm -rf src\nEOF","expect":"block","rule":"FR-6","why":"per-segment scan: the segment after ; starts with a fence verb","cwd":"repo"}
+{"id":"D131","cmd":"cat <<EOF > notes.md\n\\rm -rf src\nEOF","expect":"block","rule":"FR-6","why":"a leading backslash is stripped before the command word is matched","cwd":"repo"}
+{"id":"D132","cmd":"cat <<EOF > notes.md\n/bin/rm -rf src\nEOF","expect":"block","rule":"FR-6","why":"an absolute path is reduced to its basename before matching","cwd":"repo"}
+{"id":"D133","cmd":"cat <<EOF > notes.md\ncommand rm -rf src\nEOF","expect":"block","rule":"FR-6","why":"the command wrapper prefix is stripped","cwd":"repo"}
+{"id":"D134","cmd":"cat <<EOF > notes.md\nexec rm -rf src\nEOF","expect":"block","rule":"FR-6","why":"the exec wrapper prefix is stripped","cwd":"repo"}
+{"id":"D135","cmd":"cat <<EOF > notes.md\nsudo rm -rf src\nEOF","expect":"block","rule":"FR-6","why":"the sudo wrapper prefix is stripped","cwd":"repo"}
+{"id":"D136","cmd":"cat <<EOF > notes.md\nx=rm; $x -rf src\nEOF","expect":"block","rule":"FR-6","why":"a variable command word forces the full scan and is also scanned as rm, git and kubectl with the same arguments","cwd":"repo"}
+{"id":"D137","cmd":"cat <<EOF > notes.md\n$(rm -rf src)\nEOF","expect":"block","rule":"FR-6","why":"a command substitution under an unquoted delimiter runs when the heredoc is expanded: full scan","cwd":"repo"}
+{"id":"D138","cmd":"cat <<EOF > notes.md\n`rm -rf src`\nEOF","expect":"block","rule":"FR-6","why":"a backtick substitution under an unquoted delimiter: full scan","cwd":"repo"}
+{"id":"D139","cmd":"cat <<EOF > notes.md\neval \"rm -rf src\"\nEOF","expect":"block","rule":"FR-6","why":"an interpreter word inside the body forces the full scan","cwd":"repo"}
+{"id":"D140","cmd":"cat <<EOF > notes.md\ngit push --force origin main was refused\nEOF","expect":"block","rule":"FR-6","why":"fail closed: a prose line that begins with a fence verb is kept and scanned as a command (the documented limit of per-segment classification)","cwd":"repo"}
+{"id":"D141","cmd":"cat > notes.md <<'EOF'\n\u0001\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"a control character anywhere in the command forces the full scan","cwd":"repo"}
+{"id":"D142","cmd":"cat <<'EOF' > \"$OUT\"\nrm -rf src\nEOF","expect":"block","rule":"FR-6","why":"a non-literal write target cannot be judged: interpreter class","cwd":"repo"}
+{"id":"B89","cmd":"gh api -X DELETE repos/o/r/git/refs/heads/main --input - <<'EOF'\n{\"ref\":\"refs/heads/main\"}\nEOF","expect":"allow","rule":"FR-6","why":"documented miss (cycle-129 Sprint 2): gh api -X DELETE has no fence rule of its own; the classifier scans the body in full (D113) and a benign body passes","cwd":"repo"}

